window.__votdWeek && window.__votdWeek({"week":"2029-10-08","reading":"Doctrine and Covenants 111–114","days":[{"d":"2029-10-08","ref":"D&C 111:8","b":"D&C","c":111,"v":8,"he":"וְהַמָּקוֹם אֲשֶׁר רְצוֹנִי כִּי תֵּשְׁבוּ בּוֹ לָרֹב יִוָּדַע לָכֶם בִּשְׁלוֹם רוּחִי וּבְכֹחָהּ אֲשֶׁר יִזַּל אֲלֵיכֶם׃","en":"And the place where it is my will that you should tarry, for the main, shall be signalized unto you by the peace and power of my Spirit, that shall flow unto you."},{"d":"2029-10-09","ref":"D&C 111:11","b":"D&C","c":111,"v":11,"he":"לָכֵן הֱיוּ עֲרוּמִים כַּנְּחָשִׁים וּבְכׇל־זֹאת בְּלֹא חֵטְא וַאֲנִי אָכִין כׇּל־דָּבָר לְטוֹבַתְכֶם כְּפִי אֲשֶׁר תּוּכְלוּ לְקַבֵּל אָמֵן׃","en":"Therefore, be ye as wise as serpents and yet without sin; and I will order all things for your good, as fast as ye are able to receive them. Amen."},{"d":"2029-10-10","ref":"D&C 112:23","b":"D&C","c":112,"v":23,"he":"אָמֵן אָמֵן אֹמֵר לָכֶם חֹשֶׁךְ כִּסָּה אֶרֶץ וַעֲרָפֶל כָּבֵד דַּעַת הָעַמִּים וְכׇל־בָּשָׂר הִשְׁחִית אֶת־דַּרְכּוֹ לְפָנָי׃","en":"Verily, verily, I say unto you, darkness covereth the earth, and gross darkness the minds of the people, and all flesh has become corrupt before my face."},{"d":"2029-10-11","ref":"D&C 112:26","b":"D&C","c":112,"v":26,"he":"רִאשׁוֹנָה בָּאֵלֶּה אֲשֶׁר בֵּינֵיכֶם נְאֻם יְהוָה אֲשֶׁר אָמְרוּ לָדַעַת שְׁמִי וְלֹא יְדָעוּנִי וְגִדְּפוּ בִי בְּתוֹךְ בֵּיתִי נְאֻם יְהוָה׃","en":"First among those among you, saith the Lord, who have professed to know my name and have not known me, and have blasphemed against me in the midst of my house, saith the Lord."},{"d":"2029-10-12","ref":"D&C 113:5","b":"D&C","c":113,"v":5,"he":"מַה־הוּא שֹׁרֶשׁ יִשַׁי הַנִּזְכָּר בַּפָּסוּק הָעֲשִׂירִי לַפֶּרֶק הָאַחַד־עָשָׂר׃","en":"What is the root of Jesse spoken of in the 10th verse of the 11th chapter?"},{"d":"2029-10-13","ref":"D&C 113:6","b":"D&C","c":113,"v":6,"he":"הִנֵּה כֹּה אָמַר יְהוָה הוּא צֶאֱצָא יִשַׁי וְגַם יוֹסֵף אֲשֶׁר לוֹ מִשְׁפַּט הַכְּהֻנָּה וּמַפְתְּחוֹת הַמַּלְכוּת לְנֵס וּלְקִבּוּץ עַמִּי בְּאַחֲרִית הַיָּמִים׃","en":"Behold, thus saith the Lord, it is a descendant of Jesse, as well as of Joseph, unto whom rightly belongs the priesthood, and the keys of the kingdom, for an ensign, and for the gathering of my people in the last days."},{"d":"2029-10-14","ref":"D&C 114:2","b":"D&C","c":114,"v":2,"he":"כִּי אָמֵן כֹּה אָמַר יְהוָה כִּי כְּפִי אֲשֶׁר יֵשׁ בָּכֶם הַמְכַחֲשִׁים בִּשְׁמִי אֲחֵרִים יִנָּטְעוּ תַּחְתֵּיהֶם וְיִקְחוּ אֶת־פְּקֻדָּתָם אָמֵן׃","en":"For verily thus saith the Lord, that inasmuch as there are those among you who deny my name, others shall be planted in their stead and receive their bishopric. Amen."}]});
